import type { GameWithResults } from "@core/domain/types/index.js";

/**
 * How Dynasty results group a player across games.
 * - `"playerId"` (default): by `playerId`. Pass stable ids to `addPlayers`
 *   (`players: [{ id, name }]`) so the same person keeps one id across games.
 * - `"playerName"`: by player name, for games whose players were added
 *   without stable ids (ids are regenerated by every `addPlayers` call).
 */
export type DynastyGroupBy = "playerId" | "playerName";

export type GetDynastyResultCommand = {
  games: GameWithResults[];
  /** Grouping key across games. Defaults to `"playerId"`. */
  groupBy?: DynastyGroupBy;
};
